import { afterEach, describe, expect, test } from "bun:test";

const databasePath = `/tmp/taskboard-cli-test-${process.pid}.json`;
const cliPath = new URL("../src/cli.ts", import.meta.url).pathname;

async function invoke(...args: string[]) {
  const result = Bun.spawnSync([process.execPath, "run", cliPath, ...args], {
    env: { ...process.env, TASKBOARD_FILE: databasePath },
  });
  return { exitCode: result.exitCode, stdout: result.stdout.toString(), stderr: result.stderr.toString() };
}

afterEach(async () => {
  try { await Bun.file(databasePath).delete(); } catch { /* absent file */ }
});

describe("taskboard", () => {
  test("persists, filters, completes, deletes, and reports stats", async () => {
    const added = await invoke("add", "--title", " First task ", "--tags", "Work,work, Urgent", "--due", "2020-01-01");
    expect(added.exitCode).toBe(0);
    expect(JSON.parse(added.stdout)).toMatchObject({ id: 1, title: "First task", tags: ["work", "urgent"], status: "open" });

    expect(JSON.parse((await invoke("list", "--tag", "WORK", "--overdue", "2020-01-02")).stdout)).toHaveLength(1);
    expect(JSON.parse((await invoke("stats")).stdout)).toEqual({ total: 1, open: 1, done: 0, overdue: 1 });

    const completed = await invoke("done", "1");
    expect(JSON.parse(completed.stdout)).toMatchObject({ status: "done" });
    const repeated = await invoke("done", "1");
    expect(JSON.parse(repeated.stdout).completedAt).toBe(JSON.parse(completed.stdout).completedAt);

    expect(JSON.parse((await invoke("delete", "1")).stdout).id).toBe(1);
    expect(JSON.parse((await invoke("list")).stdout)).toEqual([]);
  });

  test("rejects invalid input without replacing malformed data", async () => {
    await Bun.write(databasePath, "not json");
    const malformed = await invoke("list");
    expect(malformed.exitCode).not.toBe(0);
    expect(await Bun.file(databasePath).text()).toBe("not json");

    await Bun.write(databasePath, JSON.stringify({ tasks: [] }));
    expect((await invoke("add", "--title", "", "--due", "2026-02-29")).exitCode).not.toBe(0);
    expect((await invoke("list", "--bad", "x")).exitCode).not.toBe(0);
  });
});

