type Status = "open" | "done";

type Task = {
  id: number;
  title: string;
  tags: string[];
  due?: string;
  status: Status;
  createdAt: string;
  completedAt?: string;
};

type Database = { tasks: Task[] };

const databasePath = process.env.TASKBOARD_FILE || ".taskboard.json";

function fail(message: string): never {
  throw new Error(message);
}

function isDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function today(): string {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60_000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

async function loadDatabase(): Promise<Database> {
  const file = Bun.file(databasePath);
  if (!(await file.exists())) return { tasks: [] };

  let parsed: unknown;
  try {
    parsed = JSON.parse(await file.text());
  } catch {
    fail("Malformed taskboard database");
  }

  if (!parsed || typeof parsed !== "object" || !Array.isArray((parsed as Database).tasks)) {
    fail("Malformed taskboard database");
  }
  return parsed as Database;
}

async function saveDatabase(database: Database): Promise<void> {
  const temporaryPath = `${databasePath}.tmp-${process.pid}-${Date.now()}`;
  try {
    await Bun.write(temporaryPath, `${JSON.stringify(database, null, 2)}\n`);
    await Bun.write(temporaryPath, Bun.file(temporaryPath));
    const result = Bun.spawnSync(["mv", temporaryPath, databasePath]);
    if (result.exitCode !== 0) fail("Unable to save taskboard database");
  } catch (error) {
    try { await Bun.file(temporaryPath).delete(); } catch { /* best effort cleanup */ }
    throw error;
  }
}

function parseFlags(args: string[], allowed: Set<string>): Map<string, string> {
  const flags = new Map<string, string>();
  for (let index = 0; index < args.length; index += 2) {
    const flag = args[index];
    const value = args[index + 1];
    if (!flag?.startsWith("--") || !allowed.has(flag) || value === undefined || flags.has(flag)) {
      fail("Invalid command arguments");
    }
    flags.set(flag, value);
  }
  return flags;
}

function normalizeTags(input: string): string[] {
  return [...new Set(input.split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
}

function taskId(value: string | undefined): number {
  if (!value || !/^\d+$/.test(value)) fail("Invalid task id");
  return Number(value);
}

async function run(): Promise<unknown> {
  const argv = process.argv.slice(2);
  if (argv[0] === "--") argv.shift();
  const [command, ...args] = argv;
  const database = await loadDatabase();

  switch (command) {
    case "add": {
      const flags = parseFlags(args, new Set(["--title", "--tags", "--due"]));
      const title = flags.get("--title")?.trim();
      if (!title) fail("Title is required");
      const due = flags.get("--due");
      if (due && !isDate(due)) fail("Invalid due date");
      const task: Task = {
        id: database.tasks.reduce((maximum, item) => Math.max(maximum, item.id), 0) + 1,
        title,
        tags: normalizeTags(flags.get("--tags") || ""),
        ...(due ? { due } : {}),
        status: "open",
        createdAt: new Date().toISOString(),
      };
      database.tasks.push(task);
      await saveDatabase(database);
      return task;
    }
    case "list": {
      const flags = parseFlags(args, new Set(["--status", "--tag", "--overdue"]));
      const status = flags.get("--status");
      const tag = flags.get("--tag")?.trim().toLowerCase();
      const overdue = flags.get("--overdue");
      if (status && status !== "open" && status !== "done") fail("Invalid status");
      if (overdue && !isDate(overdue)) fail("Invalid overdue date");
      return database.tasks.filter((task) =>
        (!status || task.status === status) &&
        (!tag || task.tags.includes(tag)) &&
        (!overdue || (task.status === "open" && !!task.due && task.due < overdue)),
      ).sort((left, right) => left.id - right.id);
    }
    case "done": {
      if (args.length !== 1) fail("Invalid command arguments");
      const task = database.tasks.find((item) => item.id === taskId(args[0]));
      if (!task) fail("Task not found");
      if (task.status === "open") {
        task.status = "done";
        task.completedAt = new Date().toISOString();
        await saveDatabase(database);
      }
      return task;
    }
    case "delete": {
      if (args.length !== 1) fail("Invalid command arguments");
      const id = taskId(args[0]);
      const index = database.tasks.findIndex((item) => item.id === id);
      if (index === -1) fail("Task not found");
      const [task] = database.tasks.splice(index, 1);
      await saveDatabase(database);
      return task;
    }
    case "stats": {
      if (args.length !== 0) fail("Invalid command arguments");
      const open = database.tasks.filter((task) => task.status === "open");
      return {
        total: database.tasks.length,
        open: open.length,
        done: database.tasks.length - open.length,
        overdue: open.filter((task) => task.due && task.due < today()).length,
      };
    }
    default:
      fail("Unknown command");
  }
}

run().then(
  (result) => console.log(JSON.stringify(result)),
  (error: unknown) => {
    console.error(error instanceof Error ? error.message : "Command failed");
    process.exit(1);
  },
);

